function odlContentSettingValue(string $base,$v):void {
 if($base==='z_index'&&(!is_numeric($v)||!is_finite((float)$v)||abs((float)$v)>10000))odlContentFail('INVALID_SETTING','Z-index musí být konečné číslo v rozsahu -10000 až 10000.');
 if($base==='text_padding'){if(!is_array($v))odlContentFail('INVALID_SETTING','Odsazení tlačítka vyžaduje objekt rozměrů.');odlContentDimension($v);}
 if($base==='link_to'&&!in_array($v,['none','file','custom'],true))odlContentFail('INVALID_SETTING','Nepodporovaný cíl odkazu obrázku.');
